    float center_x,
    float primary_y,
    float secondary_y,
    float z,
    int seed_delta_length)
{
    primary->center_x = center_x;
    primary->rotation_scalar_98 = 0.0f;
    primary->rotation_scalar_94 = 0.0f;
    primary->special_scalar = 0.0f;
    primary->lateral_scale = 1.0f;
